// `video validate` on an unsupported media format (task 037; ADR-0008; PRD §6.3).
// The project names assets/clip.avi for an image block: stage 3 reports
// E_MEDIA_FORMAT with the file and the supported list, and exits 1. The clip is
// generated by tests/fixtures/media/generate.sh, which runs first. The project
// is copied to a scratch dir, so nothing is written into tests/fixtures.
import { execFileSync, spawnSync } from "node:child_process";
import { copyFileSync, mkdirSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { delimiter, join } from "node:path";
import { fileURLToPath } from "node:url";
import { after, before, describe, it } from "node:test";
import { strict as assert } from "node:assert";

const ROOT = fileURLToPath(new URL("../..", import.meta.url));
const BIN_DIR = join(ROOT, "node_modules", ".bin");
const PROJECT = join(
  ROOT,
  "tests",
  "fixtures",
  "projects",
  "media-unsupported",
);
const SCRATCH = mkdtempSync(join(tmpdir(), "video-media-"));

/** Runs the installed `video` bin (node_modules/.bin, as `npx video` does). */
function video(args: string[], cwd: string) {
  const result = spawnSync(join(BIN_DIR, "video"), args, {
    cwd,
    encoding: "utf8",
    env: {
      ...process.env,
      PATH: `${BIN_DIR}${delimiter}${process.env["PATH"] ?? ""}`,
    },
  });
  if (result.error !== undefined) throw result.error;
  return {
    status: result.status,
    stdout: result.stdout,
    stderr: result.stderr,
  };
}

/** A scratch copy of the project, with its generated clip. */
function copyProject(): string {
  const root = join(SCRATCH, "media-unsupported");
  mkdirSync(join(root, "assets"), { recursive: true });
  copyFileSync(join(PROJECT, "index.qmd"), join(root, "index.qmd"));
  copyFileSync(
    join(PROJECT, "assets", "clip.avi"),
    join(root, "assets", "clip.avi"),
  );
  return root;
}

let root: string;

before(() => {
  execFileSync(
    "bash",
    [join(ROOT, "tests", "fixtures", "media", "generate.sh")],
    {
      stdio: "ignore",
    },
  );
  root = copyProject();
});

after(() => rmSync(SCRATCH, { recursive: true, force: true }));

describe("video validate: unsupported media format", () => {
  it("exits 1 and names assets/clip.avi and the supported image formats", () => {
    const run = video(["validate", root], ROOT);
    assert.equal(run.status, 1, run.stderr);
    assert.match(run.stderr, /assets\/clip\.avi/);
    assert.match(
      run.stderr,
      /is a \.avi file, which is not a supported image format/,
    );
    assert.match(
      run.stderr,
      /Supported image formats: \.png, \.jpg, \.jpeg, \.webp, \.svg/,
    );
    assert.equal(run.stdout, "");
  });

  it("reports E_MEDIA_FORMAT with the asset path and scene in --json", () => {
    const run = video(["validate", "--json", root], ROOT);
    assert.equal(run.status, 1, run.stderr);
    const [diagnostic] = JSON.parse(run.stdout) as Record<string, unknown>[];
    assert.deepEqual(
      {
        severity: diagnostic?.["severity"],
        code: diagnostic?.["code"],
        assetPath: diagnostic?.["assetPath"],
        sceneId: diagnostic?.["sceneId"],
        file: diagnostic?.["file"],
      },
      {
        severity: "error",
        code: "E_MEDIA_FORMAT",
        assetPath: "assets/clip.avi",
        sceneId: "scene-001",
        file: "index.qmd",
      },
    );
  });
});
